   109|function getLatestRecord<T>(value: unknown): T | null {
   110|  if (Array.isArray(value)) {
   111|    const firstValid = value.find((item) => item && typeof item === 'object');
   112|    return (firstValid as T | undefined) ?? null;
   113|  }
   114|
   115|  if (value && typeof value === 'object') {
   116|    return value as T;
   117|  }
   118|
   119|  return null;
   120|}
