   130|
   131|  return {
   132|    status: typeof record.status === 'string' ? record.status : 'unknown',
   133|    services: rawServices
   134|      .filter((item): item is Record<string, unknown> => !!item && typeof item === 'object')
   135|      .map((item) => ({
   136|        name: typeof item.name === 'string' ? item.name : 'Service',
   137|        status: typeof item.status === 'string' ? item.status : 'unknown',
   138|        responseTime: Number(item.responseTime ?? 0)})),
